const e=t=>{const r=typeof t=="string"?new Date(t):t;return new Intl.DateTimeFormat("en-US",{hour:"numeric",minute:"2-digit",hour12:!0}).format(r)},n=t=>{const r=typeof t=="string"?new Date(t):t;return new Intl.DateTimeFormat("en-US",{weekday:"short",month:"short",day:"numeric"}).format(r)},o=(t,r="GHS")=>new Intl.NumberFormat("en-GH",{style:"currency",currency:r}).format(t);export{o as a,n as b,e as f};
